        int N = sc.nextInt();
        int C = sc.nextInt();

        boolean[] infectedByOther = new boolean[N + 1];

        for (int c = 0; c < C; c++) {
            int P = sc.nextInt();
            int I = sc.nextInt();

            for (int i = 0; i < I; i++) {
                int x = sc.nextInt();
                infectedByOther[x] = true;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            if (!infectedByOther[i]) {
                sb.append(i).append('\n');
            }
        }

        System.out.print(sb);
    }
}
